class Solution {
    public int searchInsert(int[] nums, int target) {
        for (int i = 0; i < nums.length; i++) {
            if (nums[i] >= target) return i;   // 第一个不小于的位置
        }
        return nums.length;   // 全都更小，插在末尾
    }
}

class Solution {
    public int searchInsert(int[] nums, int target) {
        int left = 0, right = nums.length - 1;

        while (left <= right) {              // 闭区间，必须用 <=
            int mid = left + (right - left) / 2;   // 防溢出
            if (nums[mid] == target) {
                return mid;
            } else if (nums[mid] < target) {
                left = mid + 1;
            } else {
                right = mid - 1;
            }
        }
        // 退出时 left 就是第一个大于 target 的位置 = 插入点
        return left;
    }
}

class Solution {
    public int searchInsert(int[] nums, int target) {
        int left = 0, right = nums.length;   // 左闭右开

        while (left < right) {               // 不是 <=
            int mid = left + (right - left) / 2;
            if (nums[mid] < target) {
                left = mid + 1;
            } else {
                right = mid;                 // mid 可能是答案，不要减 1
            }
        }
        return left;   // 收敛点就是第一个 >= target 的位置
    }
}
